-- clean-start copies for reset_my_demo()
select h.id, to_jsonb(h), coalesce((select jsonb_agg(to_jsonb(c)) from public.checks c where c.user_id = h.id), '[]') from public.helpers h where h.id = 'f98c31f9-d561-46bd-abd1-3840d53305e9'
union all
select f.id, to_jsonb(f), coalesce((select jsonb_agg(to_jsonb(c)) from public.checks c where c.user_id = f.id), '[]') from public.families f where f.id = 'a02a5be1-cc30-4dc9-a164-a312d15cbc50';

-- the sample profiles that "liked you" in the demo like the two shared sign-ins too
select p.id, d.id from public.profiles p join public.profiles d on d.demo_login and d.side <> p.side
where p.is_seed and not p.demo_login and p.seed_likes_new on conflict do nothing;

commit;

select (select count(*) from public.profiles where is_seed) as sample_accounts, (select count(*) from public.helpers) as helpers, (select count(*) from public.families) as families, (select count(*) from public.checks) as checks, (select count(*) from public.likes) as likes;
