  ('42f5c2e7-d3b2-409e-aee0-f4782cfed5d7', 'Rosalinda', 'D', 38, 'makati', 'ncr', array['nanny', 'housekeeper']::text[], '{"nanny":12}'::jsonb, array['childcare', 'cooking', 'laundry', 'firstaid']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 14000, 'live-in', array['sun']::text[], array['makati']::text[], '2w', 'Twelve years caring for little ones in Makati. Patient, organized, and I love packing baon for school days.', 'Packing baon for school days.', 'asset:rosalinda.jpg', 24, 'Hello po! Ako si Rosalinda, labindalawang taon na akong yaya dito sa Makati. Mahilig ako sa routine: tulog, kain, laro, at baon tuwing may pasok.', '[{"text":"Our kids adored her. Always on time with naps and meals.","who":"Reyes family · Makati"},{"text":"Five years with us. Parang kapamilya na talaga.","who":"Cruz family · Pasig"},{"text":"Very organized, kept a daily log for us.","who":"Lim family · Makati"}]'::jsonb, '[{"years":"2019–2025","text":"Family in Makati, 2 kids (3 and 6)"},{"years":"2014–2019","text":"Family in Pasig, newborn until age 5"},{"years":"2013–2014","text":"Daycare assistant, Batangas"}]'::jsonb, 'f', 12, 'Can start in 2 weeks · Sundays off', false),
  ('1a816087-1c4b-4ab5-ae8b-8827108a0538', 'Jenny', 'P', 29, 'qc', 'ncr', array['housekeeper', 'cook']::text[], '{"housekeeper":6}'::jsonb, array['cooking', 'laundry']::text[], array[]::text[], false, array['tagalog', 'english', 'bisaya']::text[], 11000, 'live-out', array['sat', 'sun']::text[], array['qc']::text[], '1m', 'Masarap ako magluto, lalo na sinigang at adobo. Malinis sa bahay at maayos sa laundry.', 'Sunday sinigang na ulit-ulitin ng buong pamilya.', 'asset:jenny.jpg', 31, 'Hi po, ako si Jenny. Anim na taon na akong kasambahay at tagaluto. Specialty ko ang sinigang at adobo, at maayos ako sa laundry.', '[{"text":"Best kare-kare we''ve had at home.","who":"Santos family · QC"},{"text":"Neat, quiet and reliable every single day.","who":"Aquino family · QC"}]'::jsonb, '[{"years":"2021–2025","text":"Family of 5 in Quezon City"},{"years":"2019–2021","text":"Kitchen helper, carinderia in Cubao"}]'::jsonb, 'f', 6, 'Weekdays, 7 AM to 5 PM · Start next month', false),
