  ('1b831d5a-9185-4802-a653-4b2dabab2e39', 'Lorna', 'C', 52, 'manila', 'ncr', array['allaround']::text[], '{"allaround":24}'::jsonb, array['cooking', 'laundry', 'childcare']::text[], array[]::text[], false, array['tagalog', 'bisaya']::text[], 13000, 'live-in', array['sun']::text[], array['manila']::text[], '1m', 'Mahigit 20 taon na akong kasambahay, kasama ang apat na taon sa Hong Kong. Ako na bahala sa luto, linis, at laba. Parang pamilya ko na ang inaalagaan ko.', 'Seeing the kids I raised graduate.', 'asset:lorna.jpg', 33, 'Ako po si Lorna. Mahigit dalawampung taon na akong kasambahay, kasama ang apat na taon sa Hong Kong. Ako na po ang bahala sa bahay.', '[{"text":"Fifteen years with us. She raised our kids with love.","who":"Villanueva family · Malate"},{"text":"Masipag at tapat. Hindi ka magsisisi.","who":"Dizon family · Sampaloc"}]'::jsonb, '[{"years":"2010–2025","text":"One family in Malate, kids grown up with me"},{"years":"2005–2010","text":"Household of 7 in Sampaloc"},{"years":"2001–2005","text":"Family with 2 kids, Hong Kong"}]'::jsonb, 'f', 24, 'Available in 1 month · Sunday off', false),
  ('11775253-67d5-43d2-a6f8-4515a7d4bfbc', 'Arnel', 'G', 41, 'makati', 'ncr', array['driver']::text[], '{"driver":14}'::jsonb, array['driving']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 18000, 'live-out', array['sun']::text[], array['makati']::text[], '2w', 'Professional driver, no violations on my record. Kabisado ang Metro Manila at school runs. Maingat at laging on time.', 'Getting the kids to school early, kahit traffic.', 'asset:arnel.jpg', 28, 'Good day po, ako si Arnel. Labing-apat na taon na akong driver. Kabisado ko ang Makati hanggang Alabang, at laging maaga.', '[{"text":"Calm driver, the kids felt safe every day.","who":"Ocampo family · Makati"},{"text":"Always early, car always clean.","who":"Yap family · Makati"}]'::jsonb, '[{"years":"2016–2025","text":"Family driver, Makati to Alabang school runs"},{"years":"2011–2016","text":"Company service driver, Ortigas"}]'::jsonb, 'm', 14, 'Mon–Sat · Can start next week', false),
  ('05751ef6-8ee7-4791-af3b-0aece6aa9c92', 'Grace', 'T', 33, 'cebu', 'r7', array['nanny']::text[], '{"nanny":9}'::jsonb, array['childcare', 'firstaid', 'cooking']::text[], array[]::text[], false, array['bisaya', 'tagalog', 'english']::text[], 9500, 'live-in', array['sun']::text[], array['cebu']::text[], 'now', 'Mahilig ako sa bata. 9 years as yaya, marunong mag-first aid at mag-prepare ng baby food.', 'First steps and first words. Twice, with twins!', 'asset:grace.jpg', 35, 'Maayong adlaw! Ako si Grace, siyam na taon nang yaya. Nag-alaga ako ng kambal, at marunong ako sa first aid at baby food.', '[{"text":"Handled our twins like a pro. Lovely with babies.","who":"Garcia family · Cebu City"},{"text":"Gentle and very clean with baby bottles and food.","who":"Lao family · Mandaue"}]'::jsonb, '[{"years":"2020–2025","text":"Twins from 6 months to 5 years, Cebu City"},{"years":"2016–2020","text":"Family with a toddler, Mandaue"}]'::jsonb, 'f', 9, 'Available now', false),
  ('98bb9674-a4d3-431f-a616-ca30e3cf0732', 'Mylene', 'R', 36, 'bgc', 'ncr', array['cook']::text[], '{"cook":11}'::jsonb, array['cooking']::text[], array[]::text[], false, array['tagalog', 'english', 'hiligaynon']::text[], 17000, 'live-out', array['sat', 'sun']::text[], array['bgc']::text[], '2w', 'Cooked for families and a small catering business. Kaya ko ang Filipino, Japanese, at healthy meal prep.', 'Planning a week of meals the family looks forward to.', 'asset:mylene.jpg', 30, 'Hi! Ako si Mylene. Nagluto ako para sa mga pamilya at catering. Kaya ko ang Filipino, Japanese, at healthy meal prep.', '[{"text":"Her katsu and sinigang are both amazing.","who":"Nakamura family · BGC"},{"text":"Weekly meal prep saved our weeknights.","who":"Fernandez family · Makati"},{"text":"Clean kitchen, smart grocery budget.","who":"Aguilar family · BGC"}]'::jsonb, '[{"years":"2019–2025","text":"Private cook for an expat family, BGC"},{"years":"2014–2019","text":"Catering cook, Iloilo City"}]'::jsonb, 'f', 11, 'Mon–Fri, lunch and dinner', false),
  ('1f5e6cfa-dbad-4ea6-a5ac-415099192f26', 'Rodel', 'S', 48, 'pasig', 'ncr', array['driver', 'allaround']::text[], '{"driver":16}'::jsonb, array['driving', 'laundry']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 15000, 'live-in', array['sun']::text[], array['pasig']::text[], '1m', 'Driver at all-around sa bahay. Marunong din sa minor repairs at garden. Responsable at maaasahan.', 'Fixing things before anyone notices they broke.', 'asset:rodel.jpg', 25, 'Ako po si Rodel, driver at all-around. Marunong din ako sa minor repairs at garden. Responsable po ako.', '[{"text":"Fixes everything, drives safely, always polite.","who":"Domingo family · Pasig"}]'::jsonb, '[{"years":"2012–2025","text":"Driver and handyman for a family in Pasig"},{"years":"2009–2012","text":"Delivery driver"}]'::jsonb, 'm', 16, 'Available in 1 month', false),
  ('c78cd49d-c1d8-4b24-a811-ae40c668b9a6', 'Cecilia', 'L', 42, 'makati', 'ncr', array['nanny', 'caregiver']::text[], '{"nanny":13}'::jsonb, array['childcare', 'firstaid', 'cooking']::text[], array[]::text[], false, array['tagalog', 'english', 'ilocano']::text[], 15500, 'live-in', array['sun']::text[], array['makati']::text[], '2w', 'I''ve cared for newborns and for a lola with dementia. Gentle, calm, and I keep a care log for parents.', 'Keeping a care log so parents never miss a thing.', 'asset:cecilia.jpg', 32, 'Hello po, ako si Cecilia. Nag-alaga ako ng mga newborn at ng isang lola na may dementia. Kalmado ako at may care log para sa mga magulang.', '[{"text":"Our first baby, and she made us feel so prepared.","who":"Mendoza family · Makati"},{"text":"So patient with our lola. Forever grateful.","who":"Salazar family · Parañaque"},{"text":"Strict but loving with the kids.","who":"Rivera family · Laoag"}]'::jsonb, '[{"years":"2020–2025","text":"Newborn care, family in Makati"},{"years":"2015–2020","text":"Lola with dementia, Parañaque"},{"years":"2012–2015","text":"Nanny for 3 kids, Laoag"}]'::jsonb, 'f', 13, 'Can start in 3 weeks', false),
