  ('8776ba00-c769-4b22-a900-c83bbddeb494', 'Bernadette', 'K', 30, 'bgc', 'ncr', array['nanny']::text[], '{"nanny":6}'::jsonb, array['childcare', 'tutoring', 'firstaid']::text[], array[]::text[], false, array['english', 'tagalog']::text[], 16000, 'live-out', array['sat', 'sun']::text[], array['bgc']::text[], '1m', 'Worked with expat families for 6 years. Fluent English, I help with homework and swim lesson drop-offs.', 'Homework time that ends with a high five.', 'asset:bernadette.jpg', 31, 'Hi! I am Bernadette. I have worked with expat families for six years. I help with homework and school drop-offs.', '[{"text":"Our kids'' favourite person in Manila.","who":"Walker family · BGC"},{"text":"Reliable, warm and great with homework.","who":"Kim family · Makati"}]'::jsonb, '[{"years":"2022–2025","text":"Australian family in BGC, 2 kids (5 and 8)"},{"years":"2019–2022","text":"Korean family in Makati, 1 kid"}]'::jsonb, 'f', 6, 'Weekdays · Start next month', false),
  ('82156ec1-097b-4e1b-a417-7bcac9ca6db8', 'Noel', 'A', 44, 'cebu', 'r7', array['allaround', 'driver']::text[], '{"allaround":12}'::jsonb, array['driving', 'petcare']::text[], array[]::text[], false, array['bisaya', 'tagalog']::text[], 11000, 'live-in', array['sun']::text[], array['cebu']::text[], '1m', 'All-around sa bahay: driver, hardinero, ayos ng gripo at kuryente. Kasama ang pamilya, parang tito na.', 'Weekend garden days with the family dogs.', 'asset:noel.jpg', 26, 'Ako si Noel, all-around sa bahay: driver, hardinero, at ayos ng gripo. Mahal ko rin ang mga aso.', '[{"text":"Handy, honest, and great with our dogs.","who":"Sy family · Cebu City"}]'::jsonb, '[{"years":"2013–2025","text":"Family in Banilad, Cebu City"},{"years":"2010–2013","text":"Resort maintenance, Mactan"}]'::jsonb, 'm', 12, 'Available in 1 month', false),
