  ('e436d9b4-9ecc-455b-a394-dd876a680acd', 'Nakamura', 'makati', 'ncr', array['nanny', 'cook']::text[], array[4]::int[], false, array['cat']::text[], array['english', 'tagalog']::text[], 'live-in', 'full', array['sun']::text[], null, 18000, 22000, array['ownRoom', 'hmo']::text[], null, 'Japanese–Filipino family with one curious four-year-old and a lazy cat named Mochi.', 'expat', 3, '[{"text":"Very kind. They paid for my cooking class.","who":"Former nanny · 2 yrs"}]'::jsonb, 'Quiet hours after 9 PM. Japanese and Filipino food both welcome.', false),
  ('7ca766ff-2032-4944-aa68-5965749f9160', 'Villanueva', 'bgc', 'ncr', array['housekeeper']::text[], array[3, 8]::int[], false, array['dog', 'dog']::text[], array['tagalog']::text[], 'live-in', 'full', array['sun']::text[], null, 10000, 13000, array['ownRoom']::text[], null, 'Papa is a seafarer, home three months a year. Mama works from home and needs help keeping the house running.', 'ofw', 4, '[{"text":"Malambing ang mga bata at mababait ang aso.","who":"Former housekeeper · 2 yrs"}]'::jsonb, 'Dalawa ang aso namin, kaya kailangan okay ka sa pets.', false),
  ('8c17006e-1cec-44c8-a079-7d04e3ab8d66', 'Garcia', 'cebu', 'r7', array['cook', 'allaround']::text[], array[6, 11, 14]::int[], false, array[]::text[], array['bisaya', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 9000, 11000, array['ownRoom', 'fareHome']::text[], null, 'Big, noisy, happy family in Cebu City. We need help with meals and keeping up with three kids.', 'filipino', 5, '[{"text":"I ate with them every night. Warm family.","who":"Former cook · 4 yrs"},{"text":"Kind parents, fair hours, Sunday always off.","who":"Former nanny · 3 yrs"},{"text":"Busy house but very appreciative.","who":"Former helper · 1 yr"}]'::jsonb, 'Family dinner at 7 PM, and everyone eats together.', false),
  ('db1d89d5-c76d-44be-ae5c-260eb5fa1ee7', 'Andersen', 'bgc', 'ncr', array['housekeeper']::text[], array[]::int[], false, array['dog', 'dog']::text[], array['english']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '8:00–17:00', 13000, 16000, array['load']::text[], null, 'Danish couple working long hours in BGC. Looking for help with cleaning, laundry and two golden retrievers.', 'expat', 2, '[{"text":"Easy to work with, very respectful.","who":"Former housekeeper · 1 yr"}]'::jsonb, 'Dogs walk at 7 AM and 6 PM. No kids, just two very friendly dogs.', false),
  ('0e131853-498a-48e5-a02f-33393ed6b09e', 'Lim', 'cebu', 'r7', array['caregiver']::text[], array[]::int[], true, array[]::text[], array['bisaya', 'english', 'tagalog']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '8:00–17:00', 12000, 15000, array['load']::text[], null, 'Our father is recovering from a mild stroke. We need a caregiver who is patient and encouraging.', 'filipino', 3, '[{"text":"Supportive family, always available when needed.","who":"Former caregiver · 2 yrs"}]'::jsonb, 'Papa has therapy Tuesdays and Fridays; we need help on those trips.', false),
  ('9c8bb0a7-e640-46c0-ae19-e60a68ff81f6', 'Bautista', 'makati', 'ncr', array['nanny']::text[], array[5, 7]::int[], false, array[]::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 11000, 14000, array['ownRoom', 'load', 'fareHome']::text[], '2026-11-23', 'Mama works in Hong Kong. Papa runs a small business from home and needs help with the kids'' routines.', 'ofw', 4, '[{"text":"Si Sir ay maalalahanin at patas.","who":"Former nanny · 3 yrs"},{"text":"Good communication with Ma''am even from abroad.","who":"Former housekeeper · 1 yr"}]'::jsonb, 'Homework muna bago cellphone. Si Papa ang kasama sa bahay.', false),
  ('470aad04-c5a3-4bee-af86-d9d96b2488eb', 'Okafor', 'bgc', 'ncr', array['nanny', 'housekeeper']::text[], array[2, 4, 9]::int[], false, array[]::text[], array['english']::text[], 'live-in', 'full', array['sun']::text[], null, 17000, 21000, array['ownRoom', 'hmo']::text[], null, 'Nigerian–Filipino family of five. Three energetic kids and a lot of love (and laundry).', 'expat', 5, '[{"text":"Lively household, very generous family.","who":"Former nanny · 2 yrs"}]'::jsonb, 'Church on Sunday mornings, and Sundays are your day off.', false),
  ('a02a5be1-cc30-4dc9-a164-a312d15cbc50', 'Santos', 'makati', 'ncr', array['nanny', 'housekeeper']::text[], array[3, 6]::int[], false, array['dog']::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 12000, 15000, array['ownRoom']::text[], null, 'Two working parents in Makati with two kids, 3 and 6, and a friendly dog. We are looking for a live-in nanny who can also help around the house.', 'filipino', 4, '[]'::jsonb, null, false);
